def solve(s):
    char_count = {}
    for char in s:
        if char != ' ':
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1
    return char_count

# Example usage
s = "Hello World"
result = solve(s)
print(result)  # Output: {'H': 1, 'e': 1, 'l': 3, 'o': 2, ' ': 1, 'W': 1, 'r': 1, 'd': 1}
